pce_globals.source:
static uint8 **RAMPtrs = NULL;
static uint32 PageSize;
static uint32 NumPages;

typedef struct __CHEATF
{
   char *name;
   char *conditions;

   uint32 addr;
   uint64 val;
   uint64 compare;

   unsigned int length;
   bool bigendian;
   unsigned int icount; // Instance count
   char type;   /* 'R' for replace, 'S' for substitute(GG), 'C' for substitute with compare */
   int status;
} CHEATF;

/* Was std::vector<CHEATF>; manual growable array (ptr/count/capacity). */
static CHEATF *cheats        = NULL;
static size_t  cheats_count  = 0;
static size_t  cheats_cap    = 0;
static bool CheatsActive     = true;

pce_push.source:
static int cheats_push_back(const CHEATF *v)
{
   if(cheats_count >= cheats_cap)
   {
      size_t newcap = cheats_cap ? cheats_cap * 2 : 8;
      CHEATF *n = (CHEATF *)realloc(cheats, newcap * sizeof(CHEATF));
      if(!n)
         return 0;
      cheats = n;
      cheats_cap = newcap;
   }
   cheats[cheats_count++] = *v;
   return 1;
}

pce_add_entry.source:
static int AddCheatEntry(char *name, char *conditions, uint32 addr, uint64 val, uint64 compare, int status, char type, unsigned int length, bool bigendian)
{
 CHEATF temp;

 memset(&temp, 0, sizeof(CHEATF));

 temp.name=name;
 temp.conditions = conditions;
 temp.addr=addr;
 temp.val=val;
 temp.status=status;
 temp.compare=compare;
 temp.length = length;
 temp.bigendian = bigendian;
 temp.type=type;

 return cheats_push_back(&temp);
}

pce_add_cheat.source:
int MDFNI_AddCheat(const char *name, uint32 addr, uint64 val, uint64 compare, char type, unsigned int length, bool bigendian)
{
   char *t;

   if(!(t = strdup(name)))
      return(0);

   if(!AddCheatEntry(t, NULL, addr,val,compare,1,type, length, bigendian))
   {
      free(t);
      return(0);
   }

   MDFNMP_RemoveReadPatches();
   RebuildSubCheats();
   MDFNMP_InstallReadPatches();

   return(1);
}

pce_init.source:
bool MDFNMP_Init(uint32 ps, uint32 numpages)
{
   PageSize = ps;
   NumPages = numpages;

   RAMPtrs = (uint8 **)calloc(numpages, sizeof(uint8 *));

   CheatsActive = MDFN_GetSettingB("cheats");
   return(1);
}

pce_add_ram.source:
void MDFNMP_AddRAM(uint32 size, uint32 A, uint8 *RAM)
{
 uint32 AB = A / PageSize;
 unsigned int x;

 size /= PageSize;

 for(x = 0; x < size; x++)
 {
  RAMPtrs[AB + x] = RAM;
  if(RAM) // Don't increment the RAM pointer if we're passed a NULL pointer
   RAM += PageSize;
 }
}

pce_apply.source:
void MDFNMP_ApplyPeriodicCheats(void)
{
 size_t ci;

 if(!CheatsActive)
  return;

 for(ci = 0; ci < cheats_count; ci++)
 {
  CHEATF *chit = &cheats[ci];
  if(chit->status && chit->type == 'R')
  {
   if(!chit->conditions || TestConditions(chit->conditions))
   {
    unsigned int x;
    for(x = 0; x < chit->length; x++)
    {
     uint32 page = ((chit->addr + x) / PageSize) % NumPages;
     if(RAMPtrs[page])
     {
      uint64 tmpval = chit->val;

      if(chit->bigendian)
       tmpval >>= (chit->length - 1 - x) * 8;
      else
       tmpval >>= x * 8;

      RAMPtrs[page][(chit->addr + x) % PageSize] = tmpval;
     }
    }
   }
  }
 }
}

pce_flush.source:
void MDFN_FlushGameCheats(int nosave)
{
   size_t ci;

   for(ci = 0; ci < cheats_count; ci++)
   {
      free(cheats[ci].name);
      if(cheats[ci].conditions)
         free(cheats[ci].conditions);
   }
   cheats_count = 0;

   RebuildSubCheats();
}

pce_set.source:
void retro_cheat_set(unsigned index, bool enabled, const char *code)
{
   char name[256];
   char temp[256];
   char *codepart;

   if (code == NULL)
      return;

   sprintf(name, "N/A");
   /* code originates from the frontend and may be arbitrarily long; a plain
    * strcpy into a 256-byte stack buffer is a buffer overflow. */
   strlcpy(temp, code, sizeof(temp));
   codepart = strtok(temp, "+,;._ ");

   while (codepart)
   {
      // Cheat references are based on
      // https://gamehacking.org/system/pce
      // https://gamehacking.org/system/pcd
      //
      // accepts 1Fxxxx:xx raw format (ram)      
      // accepts 10xxxx:xx raw format (cd-ram)
      // accepts F8xxxx:xx physical address format (ram)
      if ((strlen(codepart) == 9) && (codepart[6]==':'))
      {
         uint32 a;
         uint64 v;

         codepart[6] = '\0';

         a = strtoul(codepart, NULL, 16);
         v = strtoul(codepart + 7, NULL, 16);

         // RAM region (0x1F0000 - 0x1F2000)
         //translate physical address to raw address format
         if ((a & 0xFFE000) == 0xF82000)
         {
            a &= 0x1FFF;
            a |= 0x1F0000;
         }

         // CD-RAM region (0x100000 - 0x110000)
         // translate physical address to raw address format
         // this is just guess-work and assumed the target address is always 0x10Axxx,
         // better use raw formats if possible
         if ((a & 0xFFC000) == 0x80C000)
         {
            a &= 0x1FFF;
            a |= 0x10A000;
         }

         // only accept codes in of valid address range
         // raw address = 0x1F0000 - 0x1F1FFF or physical address 0xF82xxx - 0xF83xxx (RAM) 
         // raw address = 0x0D0000 - 0x10FFFF (SYSTEM CARD RAM / CD-RAM)
         if (((a >= 0x1F0000) && (a < 0x1F2000)) ||  // main RAM
            ((a >= 0x100000) && (a < 0x110000))  ||  // CD RAM
            ((a >= 0x00D000) && (a < 0x10FFFF)))     // System Card RAM
         {
            if (!MDFNI_AddCheat(name, a, v, 0, 'R', 1, 0))
               log_cb(RETRO_LOG_DEBUG, "Failed to set code: '%s:%02x'\n", codepart,v);
            else
               log_cb(RETRO_LOG_DEBUG, "Code set: '%s:%02x'\n", codepart,v);
         }
         else
            log_cb(RETRO_LOG_DEBUG, "Invalid or unknown code: '%s:%02x'\n", codepart,v);
         /* log_cb(RETRO_LOG_DEBUG, "address=%08x v=%02x\n", a, v); */
      }
      else
         log_cb(RETRO_LOG_DEBUG, "Invalid or unknown code: '%s'\n", codepart);
      codepart = strtok(NULL,"+,;._ ");
   }
}

ws_memory.source:
typedef struct
{
   uint32 addr;
   uint64 val;
   uint32 length;
   uint8 bigendian;
   uint8 type;
} CHEATF;

static uint8 **RAMPtrs      = NULL;
static uint32 PageSize      = 0;
static uint32 NumPages      = 0;
static bool CheatsActive    = true;

static CHEATF *cheats       = NULL;
static uint32 cheat_count   = 0;
static uint32 cheat_alloc   = 0;

bool MDFNMP_Init(uint32 ps, uint32 numpages)
{
   PageSize = ps;
   NumPages = numpages;

   RAMPtrs = (uint8 **)calloc(numpages, sizeof(uint8 *));
   if (!RAMPtrs)
      return 0;

   CheatsActive = MDFN_GetSettingB("cheats");
   return 1;
}

void MDFNMP_Kill(void)
{
   if (RAMPtrs)
   {
      free(RAMPtrs);
      RAMPtrs = NULL;
   }
   if (cheats)
   {
      free(cheats);
      cheats      = NULL;
      cheat_count = 0;
      cheat_alloc = 0;
   }
}

void MDFNMP_AddRAM(uint32 size, uint32 A, uint8 *RAM)
{
   uint32 AB = A / PageSize;
   uint32 x;

   /* Round the page count up: with the 16KB cheat page size, a
    * region smaller than one page (e.g. the 8KB SRAM used by save
    * type 0x01 carts) previously mapped zero pages, making it
    * invisible to the cheat engine. Same bug exists in upstream
    * mednafen. Callers are responsible for keeping cheat
    * addresses within the real region size; the libretro cheat
    * entry point validates against SRAMSize before adding a
    * code. */
   size = (size + PageSize - 1) / PageSize;

   for (x = 0; x < size; x++)
   {
      if (AB + x >= NumPages)
         break;
      RAMPtrs[AB + x] = RAM;
      if (RAM) /* Don't increment the RAM pointer if we're passed a NULL pointer */
         RAM += PageSize;
   }
}

int MDFNI_AddCheat(const char *name, uint32 addr, uint64 val, uint64 compare, char type, unsigned int length, bool bigendian)
{
   CHEATF *slot;

   (void)name;
   (void)compare;

   if (cheat_count == cheat_alloc)
   {
      uint32 new_alloc = cheat_alloc ? (cheat_alloc << 1) : 8;
      CHEATF *new_buf  = (CHEATF *)realloc(cheats, new_alloc * sizeof(CHEATF));

      if (!new_buf)
         return 0;

      cheats      = new_buf;
      cheat_alloc = new_alloc;
   }

   slot            = &cheats[cheat_count];
   slot->addr      = addr;
   slot->val       = val;
   slot->length    = length;
   slot->bigendian = bigendian ? 1 : 0;
   slot->type      = (uint8)type;
   cheat_count++;

   return 1;
}

void MDFN_FlushGameCheats(int nosave)
{
   (void)nosave;
   cheat_count = 0;
}

void MDFNMP_ApplyPeriodicCheats(void)
{
   uint32 i;

   if (!CheatsActive)
      return;

   for (i = 0; i < cheat_count; i++)
   {
      const CHEATF *ch = &cheats[i];
      uint32 x;

      if (ch->type != 'R')
         continue;

      for (x = 0; x < ch->length; x++)
      {
         uint32 page = ((ch->addr + x) / PageSize) % NumPages;

         if (RAMPtrs[page])
         {
            uint64 tmpval = ch->val;

            if (ch->bigendian)
               tmpval >>= (ch->length - 1 - x) * 8;
            else
               tmpval >>= x * 8;

            RAMPtrs[page][(ch->addr + x) % PageSize] = (uint8)tmpval;
         }
      }
   }
}

ws_digit.source:
static INLINE int cheat_hex_digit(char c)
{
   if (c >= '0' && c <= '9')
      return c - '0';
   if (c >= 'A' && c <= 'F')
      return c - 'A' + 10;
   if (c >= 'a' && c <= 'f')
      return c - 'a' + 10;
   return -1;
}

ws_separator.source:
static INLINE int cheat_is_sep(char c)
{
   return (c == '+' || c == ',' || c == ';' || c == '.' ||
           c == '_' || c == ' ');
}

ws_set.source:
void retro_cheat_set(unsigned index, bool enabled, const char *code)
{
   const char *p = code;

   (void)index;

   if (!code || !enabled)
      return;

   while (*p)
   {
      uint32 a       = 0;
      uint32 v       = 0;
      int addr_chars = 0;
      int val_chars  = 0;
      int valid      = 1;
      const char *part_start;
      int d;

      while (cheat_is_sep(*p))
         p++;
      if (!*p)
         break;
      part_start = p;

      /* hex address, 1-6 digits */
      while ((d = cheat_hex_digit(*p)) >= 0)
      {
         if (addr_chars >= 6)
         {
            valid = 0;
            break;
         }
         a = (a << 4) | (uint32)d;
         addr_chars++;
         p++;
      }
      if (!addr_chars || addr_chars > 5)
         valid = 0;

      if (valid && *p == ':')
         p++;
      else
         valid = 0;

      /* value: exactly two hex digits */
      if (valid)
      {
         while ((d = cheat_hex_digit(*p)) >= 0)
         {
            if (val_chars >= 2)
            {
               valid = 0;
               break;
            }
            v = (v << 4) | (uint32)d;
            val_chars++;
            p++;
         }
         if (val_chars != 2)
            valid = 0;
      }

      /* the part must end exactly at a separator or the end */
      if (valid && *p && !cheat_is_sep(*p))
         valid = 0;

      if (valid)
      {
         /* RAM, or SRAM when the cart has any */
         if (a < 0x10000 || (SRAMSize && a >= 0x10000 &&
               a < 0x10000 + SRAMSize))
         {
            if (!MDFNI_AddCheat("N/A", a, v, 0, 'R', 1, false))
            {
               if (log_cb)
                  log_cb(RETRO_LOG_WARN, "Failed to set cheat: %05X:%02X\n", a, v);
            }
         }
         else if (log_cb)
            log_cb(RETRO_LOG_WARN, "Cheat address out of range: %05X:%02X\n", a, v);
      }
      else if (log_cb)
         log_cb(RETRO_LOG_WARN, "Invalid cheat code part: '%.16s'\n", part_start);

      /* advance to the next separator (recovers from junk parts) */
      while (*p && !cheat_is_sep(*p))
         p++;
   }
}
